INSERT INTO `offres` (`id`, `entreprise_id`, `titre`, `description`, `lieu`, `duree`, `remuneration`, `date_debut`, `created_at`) VALUES
(1, 1, 'Stage - Développeur/euse Java - Aix-en-Provence', 'Sopra Steria, acteur majeur de la Tech en Europe, avec 50 000 collaborateurs dans près de 30 pays, est reconnu pour ses activités de conseil, de services et solutions numériques. Il aide ses clients à mener leur transformation digitale et à obtenir des bénéfices concrets et durables. Le Groupe apporte une réponse globale aux enjeux de compétitivité des grandes entreprises et organisations, en combinant une connaissance approfondie des secteurs d’activité et des technologies à une approche collaborative.\r\n\r\nSopra Steria place l’humain au cœur de son action et s’engage auprès de ses clients à tirer le meilleur parti du numérique pour construire un avenir positif. En 2024, le Groupe a réalisé un chiffre d’affaires de 5,8 milliards d’euros.\r\n\r\nThe world is how we shape it*\r\nLe monde est tel que nous le façonnons\r\n\r\nDescription du poste\r\n\r\nIntéressé/e par la transformation digitale et les innovations technologiques ?\r\n\r\nVoici 4 bonnes raisons de rejoindre la région Sud-Est :\r\n\r\nUne variété de projets pour des entreprises locales et des grands groupes dans des secteurs divers : énergie, télécoms, transports, industrie, tertiaire, aéronautique, santé, services publics, défense\r\nDes postes diversifiés en intégration sur des domaines innovants : Cloud, Big Data, IA, SAP\r\nUn accompagnement RH, une proximité managériale et des perspectives de carrière\r\nDes équipes dynamiques à taille humaine et des communautés métier aux compétences variées.\r\nPar exemple, nous vous proposons de prendre part à l’initiative Tech’me UP qui a pour but de valoriser les filières techniques chez Sopra Steria.\r\n\r\nLes axes principaux sont les suivants :\r\n\r\nExcellence Tech : développer les compétences par du craftsmanship et de l’algorithmie, améliorer les environnements de développement pour répondre aux enjeux de time-to-market et de qualité ;\r\nImage Tech : préparation et répétition de talk en interne et en externe, conférences et rédaction de billets tech ;\r\nDéveloppement humain : permettre à chaque développeur/euse et architecte de trouver sa voie d’évolution jusqu’au plus haut niveau et mettre en lumière les compétences des expert/es !\r\nVotre rôle et vos missions :\r\n\r\nPour le compte d\'un client majeur, Sopra Steria assure une double mission dans le cadre de la gestion d\'une partie du système d\'information : maintenance corrective et évolutive et conduite de projets de développement.\r\n\r\nDans le cadre de votre alternance, vous êtes accueilli/e dans les locaux Sopra Steria au sein d\'une équipe de conception et développement et différentes responsabilités vous sont confiées :\r\n\r\nAnalyser fonctionnellement et/ou techniquement les besoins clients\r\nConcevoir, développer et tester des composants logiciels\r\nRédiger et exécuter des plans de tests de qualification et d\'intégration\r\nParticiper activement aux différentes cérémonies agiles du projet\r\nÊtre acteur/trice d\'un collectif dynamique et convivial\r\nEnvironnement technologique/fonctionnel :\r\n\r\nDes technologies avec les dernières versions du marché : Java, PHP, Angular, .Net, Springboot.\r\nUne dimension industrialisation est fortement présente sur les projets avec l\'usage de pipeline DevOps, supportés par Gitlab CI, Docker, Jenkins et le cloud Azure (AWS : Amazon Web Service).\r\nLes apports de l\'alternance :\r\n\r\nAcquérir des compétences techniques avec nos experts.\r\nDécouvrir et/ou appliquer les bonnes pratiques de développement dans un contexte professionnel.\r\nIntervenir sur les différentes phases du développement logiciel (spécification / conception / développement / déploiement).\r\nS\'approprier une méthodologie agile.\r\nS\'intégrer au sein d\'une équipe d\'environ 5/6 personnes et participer de manière active à la dynamique collective.\r\n(Re)Découvrir le fonctionnement d\'une des plus grandes ESN françaises (Entreprise de services du numérique) aux dimensions internationales.', 'Aix-en-Provence', '6', 450.00, '2026-04-06', '2026-03-30 15:10:42'),
(4, 2, 'Stage – Ingénieur Développement Logiciel Embarqué', 'Altran, groupe Capgemini, est un leader mondial du conseil en ingénierie et R&D avec plus de 50 000 ingénieurs présents dans 30 pays. Nos équipes accompagnent les plus grandes entreprises mondiales dans leur transformation technologique, de la conception à la mise en production de systèmes complexes.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du renforcement de notre practice Embedded Systems, nous recrutons un(e) stagiaire Ingénieur Développement Logiciel Embarqué pour rejoindre nos équipes à Toulouse, au cœur de la capitale aéronautique européenne.\r\n\r\nVous serez intégré(e) au sein d\'une équipe projet pluridisciplinaire travaillant pour un client du secteur aéronautique ou automobile, et vous interviendrez sur les phases de conception, développement et validation de modules logiciels embarqués critiques.\r\n\r\nVOS MISSIONS\r\n\r\n- Analyser les spécifications fonctionnelles et techniques fournies par le client\r\n- Concevoir et développer des composants logiciels embarqués en C/C++ sur systèmes temps réel\r\n- Rédiger et exécuter les plans de tests unitaires et d\'intégration\r\n- Participer aux revues de code et contribuer à l\'amélioration de la qualité logicielle\r\n- Collaborer étroitement avec les équipes hardware pour la validation système\r\n- Rédiger la documentation technique associée aux développements réalisés\r\n- Participer aux cérémonies Agile de l\'équipe (daily, sprint review, rétrospective)\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : C, C++\r\nSystèmes d\'exploitation : RTOS (FreeRTOS, VxWorks), Linux embarqué\r\nOutils : Git, JIRA, Jenkins, Eclipse, Visual Studio Code\r\nMéthodes : Agile Scrum, DO-178C (notions appréciées)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nAu cours de ce stage, vous développerez une expertise solide en développement logiciel embarqué dans un contexte industriel réel. Vous apprendrez à travailler en équipe sur des systèmes critiques, à respecter des contraintes de qualité élevées et à vous adapter aux exigences d\'un grand groupe industriel.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou en Master informatique / électronique / systèmes embarqués (Bac+4/5)\r\n- Bonnes connaissances en programmation C/C++\r\n- Notions de systèmes d\'exploitation temps réel appréciées\r\n- Rigueur, curiosité technique et esprit d\'équipe\r\n- Niveau d\'anglais technique correct (documentation en anglais)', 'Toulouse', '6 mois', 577.50, '2026-04-01', '2026-02-15 10:00:00'),
(5, 2, 'Stage – Data Scientist – Intelligence Artificielle & ML', 'Altran, filiale de Capgemini Engineering, accompagne ses clients dans la valorisation de leurs données grâce à des solutions d\'intelligence artificielle sur mesure. Notre practice Data & AI regroupe plus de 2 000 experts répartis en France et en Europe, intervenant dans des secteurs variés : industrie, énergie, transport, finance.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recherchons un(e) stagiaire Data Scientist pour rejoindre notre équipe parisienne et contribuer à des projets à fort impact pour des clients grands comptes. Vous travaillerez aux côtés d\'experts en machine learning, data engineering et MLOps sur des problématiques concrètes allant de la prédiction de pannes industrielles à l\'analyse de comportements clients.\r\n\r\nVOS MISSIONS\r\n\r\n- Collecter, nettoyer et explorer des jeux de données volumineux et hétérogènes\r\n- Développer des modèles de Machine Learning supervisés et non supervisés (classification, régression, clustering, détection d\'anomalies)\r\n- Évaluer et comparer les performances des modèles (métriques, validation croisée, courbes ROC)\r\n- Construire des pipelines de traitement de données automatisés\r\n- Déployer des modèles en production via des workflows MLOps sur Azure Machine Learning\r\n- Créer des visualisations et des dashboards pour restituer les résultats aux équipes métier\r\n- Rédiger des livrables techniques clairs à destination des clients\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : Python (Pandas, NumPy, Scikit-learn, TensorFlow, PyTorch)\r\nPlateformes cloud : Azure ML, Azure Data Factory\r\nBig Data : Apache Spark, Databricks\r\nVisualisation : Power BI, Matplotlib, Seaborn\r\nOutils : Git, Jupyter Notebook, Docker\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expérience concrète en Data Science appliquée à des problématiques industrielles réelles. Vous apprendrez à gérer un projet de bout en bout, de la compréhension du besoin métier au déploiement du modèle en production, et développerez vos compétences en communication avec les parties prenantes.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master 2 Data Science, IA, Statistiques ou école d\'ingénieur avec spécialisation Data/IA (Bac+4/5)\r\n- Maîtrise de Python et des bibliothèques de Machine Learning\r\n- Connaissances en statistiques et mathématiques appliquées\r\n- Curiosité intellectuelle, rigueur analytique et sens de la communication\r\n- Anglais professionnel requis', 'Paris', '6 mois', 600.00, '2026-04-15', '2026-02-20 10:00:00'),
(6, 3, 'Stage – Assistant Conducteur de Travaux – Construction Résidentielle', 'Bouygues Bâtiment Île-de-France est l\'une des entités phares du groupe Bouygues Construction, acteur majeur du bâtiment en France avec plus de 12 000 collaborateurs. Nous réalisons chaque année des centaines de projets allant du logement haut de gamme aux bâtiments tertiaires complexes, en passant par les équipements publics.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre d\'un projet de construction d\'un immeuble résidentiel haut de gamme de 120 logements en Île-de-France, nous recrutons un(e) stagiaire Assistant(e) Conducteur de Travaux. Vous serez directement rattaché(e) à un conducteur de travaux expérimenté qui vous accompagnera tout au long de votre stage.\r\n\r\nCe stage est une opportunité unique de découvrir le métier de conducteur de travaux dans toute sa diversité, depuis la préparation du chantier jusqu\'à la livraison, en passant par la gestion quotidienne des équipes et des sous-traitants.\r\n\r\nVOS MISSIONS\r\n\r\n- Assister le conducteur de travaux dans le suivi quotidien de l\'avancement du chantier\r\n- Coordonner les interventions des sous-traitants corps d\'état secondaires (électricité, plomberie, menuiserie)\r\n- Contrôler la conformité des travaux réalisés par rapport aux plans et aux CCTP\r\n- Participer à la gestion des approvisionnements et des commandes de matériaux\r\n- Contribuer à l\'élaboration et au suivi du planning d\'exécution\r\n- Rédiger les comptes-rendus des réunions hebdomadaires de chantier\r\n- Veiller au strict respect des règles de sécurité et des normes QHSE sur le chantier\r\n- Préparer les dossiers de réception et les levées de réserves\r\n\r\nOUTILS UTILISÉS\r\n\r\nLogiciels : AutoCAD, MS Project, Suite Office\r\nMéthodes : Lean Construction, BIM (niveau 1)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous découvrirez le fonctionnement d\'un chantier de bâtiment de A à Z, la coordination multi-corps d\'état, la gestion contractuelle avec les sous-traitants, et les enjeux de sécurité sur site. Ce stage constitue une excellente préparation à une carrière de conducteur de travaux ou chef de chantier.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur Bâtiment/Génie Civil ou BTS/DUT Génie Civil (Bac+2 à Bac+5)\r\n- Goût du terrain, sens de l\'organisation et réactivité\r\n- Capacité à travailler en équipe dans un environnement dynamique\r\n- Permis B souhaité pour les déplacements sur chantier', 'Paris', '5 mois', 550.00, '2026-04-01', '2026-02-10 10:00:00'),
(7, 3, 'Stage – Développeur(euse) Web Full Stack – DSI Bouygues Telecom', 'Bouygues Telecom, troisième opérateur télécom en France avec plus de 14 millions de clients, s\'appuie sur une DSI de plus de 1 500 collaborateurs pour concevoir, développer et maintenir ses systèmes d\'information. Dans un contexte de transformation digitale accélérée, nos équipes développent des outils innovants pour améliorer l\'expérience client et optimiser les processus internes.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez une squad produit de la DSI Bouygues Telecom et participez au développement de nouvelles fonctionnalités sur une application métier utilisée quotidiennement par plusieurs centaines de collaborateurs. Vous travaillerez en mode Agile/Scrum au sein d\'une équipe de 6 développeurs, un Product Owner et un Scrum Master.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer de nouvelles fonctionnalités front-end en React.js (composants, hooks, gestion d\'état avec Redux)\r\n- Concevoir et implémenter des endpoints API REST côté back-end en Node.js/Express\r\n- Rédiger des tests unitaires et d\'intégration (Jest, Cypress)\r\n- Participer aux cérémonies Agile : daily standup, sprint planning, sprint review, rétrospective\r\n- Contribuer aux revues de code et proposer des améliorations de la qualité du code\r\n- Optimiser les performances des pages (Lighthouse, Web Vitals)\r\n- Rédiger la documentation technique des fonctionnalités développées\r\n- Participer à la gestion de la dette technique\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nFront-end : React.js, TypeScript, Redux, SCSS\r\nBack-end : Node.js, Express, REST API\r\nBase de données : PostgreSQL, Redis\r\nDevOps : Docker, GitLab CI/CD, Kubernetes\r\nOutils : VS Code, JIRA, Confluence, Figma\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous évoluerez dans un environnement professionnel agile à grande échelle, avec des pratiques d\'engineering de haut niveau (code review, CI/CD, tests automatisés). Vous gagnerez en maturité technique et découvrirez les enjeux d\'une DSI d\'opérateur télécom.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) Bac+4/5 en informatique, développement web ou école d\'ingénieur\r\n- Maîtrise de JavaScript/TypeScript, React.js et Node.js\r\n- Connaissance de Git et des pratiques de développement collaboratif\r\n- Autonomie, esprit d\'équipe et envie d\'apprendre\r\n- Anglais technique lu/écrit', 'Paris', '6 mois', 577.50, '2026-05-01', '2026-02-25 10:00:00'),
(8, 4, 'Stage – Ingénieur Cloud & DevOps', 'Capgemini est l\'un des leaders mondiaux du conseil, des services informatiques et de la transformation digitale, avec 350 000 collaborateurs dans plus de 50 pays. En France, notre practice Cloud Infrastructure & DevOps accompagne les plus grandes entreprises dans leur migration vers le cloud et la modernisation de leurs pratiques d\'ingénierie logicielle.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recherchons un(e) stagiaire passionné(e) par le cloud et les pratiques DevOps pour rejoindre notre équipe lyonnaise. Vous interviendrez sur des projets de migration cloud et d\'automatisation pour des clients issus des secteurs de la banque, de l\'industrie et de l\'énergie.\r\n\r\nVOS MISSIONS\r\n\r\n- Accompagner les équipes client dans la migration d\'applications on-premise vers le cloud public (AWS, Azure ou GCP selon les projets)\r\n- Rédiger des scripts d\'infrastructure as code (Terraform, Pulumi) pour l\'automatisation du provisionnement\r\n- Mettre en place et maintenir des pipelines CI/CD (Jenkins, GitLab CI, GitHub Actions)\r\n- Configurer et gérer des clusters Kubernetes (EKS, AKS, GKE)\r\n- Implémenter des solutions de monitoring et d\'observabilité (Prometheus, Grafana, Datadog)\r\n- Participer à des ateliers de cadrage et de présentation de solutions chez les clients\r\n- Rédiger des guides d\'architecture et de bonnes pratiques DevOps\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nCloud : AWS (EC2, S3, RDS, Lambda), Azure (AKS, DevOps), GCP\r\nInfrastructure as Code : Terraform, Ansible, Pulumi\r\nConteneurisation : Docker, Kubernetes, Helm\r\nCI/CD : Jenkins, GitLab CI, GitHub Actions\r\nMonitoring : Prometheus, Grafana, ELK Stack\r\nLangages de scripting : Bash, Python\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une vision complète des architectures cloud modernes et des pratiques DevOps en contexte grand compte. Vous développerez des compétences techniques recherchées sur le marché et apprendrez à interagir avec des clients exigeants dans un cadre de conseil.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) Bac+4/5 en informatique, systèmes ou école d\'ingénieur\r\n- Connaissances en Linux, réseaux et scripting (Bash/Python)\r\n- Première expérience ou projets personnels sur AWS, Azure ou GCP appréciés\r\n- Certifications cloud (AWS CCP, AZ-900) un plus\r\n- Autonomie, curiosité et goût pour les défis techniques', 'Lyon', '6 mois', 600.00, '2026-04-07', '2026-01-20 10:00:00'),
(9, 4, 'Stage – Analyste Cybersécurité – Security Operations Center', 'Capgemini Cybersecurity est l\'un des leaders européens de la cybersécurité, opérant plusieurs SOC (Security Operations Centers) en France et en Europe. Nos équipes protègent les systèmes d\'information de plus de 900 clients dans des secteurs critiques : défense, énergie, banque, santé et administrations publiques.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez le SOC de Rennes, l\'un de nos centres opérationnels de cybersécurité, et participez à la surveillance et à la protection des SI de nos clients 24h/24. Vous serez intégré(e) à une équipe d\'analystes expérimentés et monterez progressivement en compétence sur des cas d\'usage réels.\r\n\r\nVOS MISSIONS\r\n\r\n- Surveiller en temps réel les alertes de sécurité remontées par les outils SIEM (Splunk, IBM QRadar, Microsoft Sentinel)\r\n- Qualifier et trier les alertes selon leur criticité (niveaux L1/L2)\r\n- Conduire des investigations approfondies sur des incidents de sécurité (analyse de logs, forensic basique)\r\n- Participer à la réponse à incidents et à la rédaction de rapports d\'analyse post-mortem\r\n- Contribuer à l\'amélioration des règles de détection (use cases SIEM)\r\n- Réaliser une veille quotidienne sur les nouvelles vulnérabilités et menaces (CVE, bulletins ANSSI, CERT-FR)\r\n- Documenter les procédures et runbooks de l\'équipe SOC\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nSIEM : Splunk, IBM QRadar, Microsoft Sentinel\r\nThreat Intelligence : MISP, VirusTotal, Shodan\r\nAnalyse réseau : Wireshark, Zeek, Suricata\r\nGestion des vulnérabilités : Nessus, Qualys\r\nFrameworks : MITRE ATT&CK, Cyber Kill Chain\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous découvrirez le fonctionnement concret d\'un SOC professionnel et développerez des compétences pratiques en détection et réponse aux incidents. Ce stage vous permettra de vous préparer aux certifications SOC Analyst (CompTIA CySA+, SANS SEC450) et constitue un tremplin idéal vers les métiers de l\'analyste cybersécurité.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master ou école d\'ingénieur spécialité Cybersécurité, Réseaux & Sécurité (Bac+4/5)\r\n- Connaissances en réseaux (TCP/IP, DNS, HTTP, firewall) et systèmes (Windows, Linux)\r\n- Curiosité pour les menaces informatiques et les techniques d\'attaque\r\n- Rigueur, capacité d\'analyse et réactivité face aux incidents\r\n- Discrétion et respect de la confidentialité des données clients', 'Rennes', '6 mois', 577.50, '2026-05-01', '2026-02-01 10:00:00'),
(10, 5, 'Stage – Ingénieur Bureau d\'Études VRD', 'Colas est l\'un des leaders mondiaux de la construction et de l\'entretien des infrastructures de transport, avec 55 000 collaborateurs présents dans plus de 50 pays. En France, nos filiales régionales réalisent chaque année des milliers de kilomètres de routes, pistes cyclables, aménagements urbains et réseaux souterrains. Colas Sud-Est intervient sur l\'ensemble de la région PACA et Corse.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du développement de son activité en région PACA, Colas Sud-Est recherche un(e) stagiaire Bureau d\'Études pour renforcer son équipe de conception de projets de voirie et réseaux divers. Vous interviendrez sur des projets variés : aménagements de voiries communales, zones d\'activités, plateformes logistiques et espaces publics.\r\n\r\nVOS MISSIONS\r\n\r\n- Réaliser des études de conception de voirie : plans de masse, plans d\'exécution, profils en long et en travers\r\n- Utiliser les logiciels de CAO/DAO spécialisés BTP (AutoCAD, Covadis, Mensura)\r\n- Effectuer les calculs de cubatures et de métrés pour les chiffrages\r\n- Participer à la rédaction de mémoires techniques et de DPGF (Décomposition du Prix Global et Forfaitaire)\r\n- Assister aux réunions de coordination avec les maîtres d\'œuvre et maîtres d\'ouvrage\r\n- Réaliser des études de faisabilité et comparer des variantes techniques\r\n- Contribuer à la réalisation des dossiers de consultation des entreprises (DCE)\r\n\r\nOUTILS UTILISÉS\r\n\r\nCAO/DAO : AutoCAD 2024, Covadis, Mensura\r\nBureautique : Suite Office, Project\r\nSIG : QGIS (notions appréciées)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expérience complète en ingénierie des travaux publics, de la conception à la consultation. Vous apprendrez à lire et produire des plans techniques, à maîtriser les logiciels métier et à travailler en équipe pluridisciplinaire sur des projets réels.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en DUT Génie Civil, BTS Travaux Publics ou Licence Pro Génie Civil (Bac+2 à Bac+3)\r\n- Connaissance d\'AutoCAD indispensable\r\n- Rigueur, sens du détail et organisation\r\n- Débutant(e) accepté(e) si motivation démontrée', 'Marseille', '4 mois', 530.00, '2026-04-14', '2026-02-05 10:00:00'),
(11, 5, 'Stage – Assistant(e) Chef de Projet Infrastructure Routière', 'Colas Aquitaine, filiale régionale du groupe Colas, est un acteur incontournable des travaux publics en Nouvelle-Aquitaine avec plus de 1 200 collaborateurs. Nous intervenons sur des projets d\'envergure : réhabilitation de routes nationales, construction d\'échangeurs autoroutiers, aménagement de zones portuaires et pistes aéroportuaires.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre d\'un programme pluriannuel de réhabilitation de routes nationales en Gironde, Colas Aquitaine recrute un(e) stagiaire Assistant(e) Chef de Projet pour renforcer son équipe de direction de travaux. Vous serez au cœur de la gestion opérationnelle d\'un chantier de grande envergure.\r\n\r\nVOS MISSIONS\r\n\r\n- Assister le chef de projet dans le pilotage quotidien du chantier\r\n- Gérer les relations contractuelles et opérationnelles avec les sous-traitants spécialisés\r\n- Analyser les écarts entre planning prévisionnel et réel et proposer des mesures correctives\r\n- Suivre les consommations budgétaires et préparer les situations de travaux mensuelles\r\n- Coordonner les approvisionnements en matériaux et équipements\r\n- Préparer et animer les réunions hebdomadaires de chantier\r\n- Rédiger les rapports d\'avancement à destination de la maîtrise d\'ouvrage\r\n- Veiller au respect des procédures QHSE et environnementales\r\n\r\nOUTILS UTILISÉS\r\n\r\nPlanification : MS Project, Excel avancé\r\nDAO : AutoCAD (notions)\r\nGestion : logiciel de gestion chantier interne Colas\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez des compétences managériales et techniques en gestion de projet de travaux publics. Vous apprendrez à piloter un projet complexe avec de nombreuses parties prenantes, à gérer des imprévus sur chantier et à communiquer efficacement avec des interlocuteurs variés.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master Génie Civil / Travaux Publics (Bac+4/5)\r\n- Première expérience en chantier TP souhaitée (stage ouvrier ou chantier école)\r\n- Maîtrise d\'Excel et de MS Project\r\n- Leadership naturel, sens de l\'organisation et résistance au stress\r\n- Permis B indispensable', 'Bordeaux', '6 mois', 550.00, '2026-06-01', '2026-03-01 10:00:00'),
(12, 6, 'Stage – Ingénieur(e) Structure Bâtiment Tertiaire', 'Eiffage Construction est l\'une des principales entités du groupe Eiffage, 4ème groupe de BTP européen avec un chiffre d\'affaires de plus de 21 milliards d\'euros. Notre direction Île-de-France réalise chaque année des projets ambitieux : sièges sociaux, campus universitaires, hôtels 5 étoiles, centres commerciaux et bâtiments de bureaux de grande hauteur.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recrutons un(e) stagiaire Ingénieur(e) Structure pour rejoindre notre service Structure & Génie Civil sur un projet de construction d\'un immeuble de bureaux tertiaire de 25 000 m² en Île-de-France. Vous travaillerez en étroite collaboration avec les ingénieurs structure et les équipes de maîtrise d\'œuvre.\r\n\r\nVOS MISSIONS\r\n\r\n- Réaliser des calculs de dimensionnement d\'éléments de structure (poteaux, poutres, dalles en béton armé, charpente métallique)\r\n- Utiliser les logiciels de modélisation et calcul de structure (Robot Structural Analysis, ETABS, GRAITEC)\r\n- Rédiger des notes de calcul conformes aux eurocodes (EC2, EC3)\r\n- Préparer et contrôler les plans d\'exécution structure en lien avec les dessinateurs\r\n- Participer aux réunions de coordination avec les autres corps d\'état (architecture, fluides, électricité)\r\n- Contribuer à la démarche BIM du projet (Revit Structure, coordination maquette numérique)\r\n- Vérifier la conformité des ouvrages réalisés par rapport aux plans approuvés\r\n\r\nENVIRONNEMENT TECHNIQUE\r\n\r\nCalcul de structure : Robot Structural Analysis, ETABS, GRAITEC Arche\r\nBIM : Revit Structure, Navisworks\r\nDAO : AutoCAD, Advance Steel\r\nNormes : Eurocodes EC2 (béton armé), EC3 (acier), EC8 (sismique)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nCe stage vous permettra d\'acquérir une expérience concrète en calcul de structure sur un projet tertiaire d\'envergure. Vous maîtriserez les logiciels de calcul professionnels, les eurocodes et les pratiques BIM en usage dans les bureaux d\'études structure.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master Génie Civil spécialité Structures ou en école d\'ingénieur (Bac+4/5)\r\n- Bonnes bases en mécanique des structures et résistance des matériaux\r\n- Connaissance d\'au moins un logiciel de calcul de structure appréciée\r\n- Rigueur, méthode et précision dans les calculs\r\n- Sens du travail en équipe pluridisciplinaire', 'Paris', '6 mois', 577.50, '2026-04-01', '2026-02-12 10:00:00'),
(13, 6, 'Stage – Chargé(e) de Mission QSE Chantier', 'Eiffage Énergie Systèmes, filiale du groupe Eiffage, est un acteur majeur des installations électriques et des systèmes d\'énergie en France avec 30 000 collaborateurs. Nos équipes régionales Auvergne-Rhône-Alpes interviennent sur des chantiers variés : bâtiments industriels, centres de données, installations photovoltaïques et réseaux de distribution d\'énergie.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du renforcement de sa politique QHSE, Eiffage Énergie Systèmes recherche un(e) stagiaire Chargé(e) de Mission QSE pour accompagner ses équipes sur les chantiers de la région grenobloise. Vous serez rattaché(e) au Responsable QHSE régional et aurez un rôle opérationnel sur plusieurs chantiers simultanément.\r\n\r\nVOS MISSIONS\r\n\r\n- Animer la démarche QHSE sur les chantiers sous votre responsabilité\r\n- Réaliser des audits internes réguliers et rédiger les rapports avec plans d\'action\r\n- Mettre à jour et suivre le Plan Particulier de Sécurité et de Protection de la Santé (PPSPS)\r\n- Préparer et animer les causeries sécurité hebdomadaires avec les équipes\r\n- Analyser les accidents du travail et presqu\'accidents, identifier les causes racines\r\n- Suivre les indicateurs sécurité (taux de fréquence, taux de gravité) et proposer des axes d\'amélioration\r\n- Contribuer à la certification ISO 14001 de l\'agence\r\n- Vérifier la conformité réglementaire des équipements et des pratiques sur site\r\n\r\nOUTILS UTILISÉS\r\n\r\nGestion QHSE : logiciel Intelex (QHSE management)\r\nDocumentation : Suite Office, SharePoint\r\nRéglementation : Code du travail, normes NF, directives européennes\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expérience terrain précieuse en management de la sécurité sur des chantiers électriques et énergétiques. Vous développerez vos compétences en animation d\'équipes, en analyse de risques et en réglementation QHSE, des compétences très recherchées dans le secteur du BTP.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master QSE, HSE, ou école d\'ingénieur avec spécialisation Sécurité / Environnement (Bac+3 à Bac+5)\r\n- Connaissance de la réglementation santé/sécurité au travail\r\n- Aisance relationnelle pour travailler avec des équipes terrain\r\n- Rigueur, réactivité et sens des responsabilités\r\n- Permis B indispensable pour les déplacements sur chantiers', 'Grenoble', '5 mois', 530.00, '2026-05-04', '2026-03-10 10:00:00'),
(14, 7, 'Stage – Assistant(e) Conducteur de Travaux Gros Œuvre', 'GTM Construction, filiale de Vinci Construction France, est l\'un des acteurs de référence de la construction de bâtiments complexes en France. Avec plus de 1 500 collaborateurs, nous réalisons chaque année des projets emblématiques : tours de bureaux, hôtels internationaux, logements collectifs haut de gamme et équipements culturels. Notre agence de Lyon participe activement au développement du quartier Part-Dieu.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre de la construction d\'un immeuble de bureaux de 18 étages au cœur du quartier Part-Dieu à Lyon, GTM Construction recrute un(e) stagiaire Assistant(e) Conducteur de Travaux spécialisé(e) en Gros Œuvre. Vous serez au contact quotidien des équipes de chantier et du conducteur de travaux principal.\r\n\r\nVOS MISSIONS\r\n\r\n- Assister le conducteur principal dans la gestion des travaux de gros œuvre (fondations, structure béton armé, maçonnerie)\r\n- Contrôler la qualité des ouvrages réalisés (conformité aux plans, tolérances dimensionnelles, finitions)\r\n- Participer à la gestion des approvisionnements et à la coordination des livraisons sur un chantier urbain contraint\r\n- Rédiger les procès-verbaux de réception des travaux et les fiches de non-conformité\r\n- Contribuer à la mise à jour du planning détaillé (niveau 3) avec MS Project\r\n- Assister aux réunions de chantier hebdomadaires avec la maîtrise d\'œuvre\r\n- Veiller au respect des règles de sécurité et au rangement du chantier\r\n\r\nOUTILS UTILISÉS\r\n\r\nPlanification : MS Project\r\nBIM : Dalux (lecture de maquettes sur tablette)\r\nDocumentation : Suite Office, SharePoint chantier\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous vivrez l\'expérience unique d\'un grand chantier urbain avec toutes ses contraintes (logistique, voisinage, réseaux souterrains) et ses challenges techniques. Vous développerez une vision complète du métier de conducteur de travaux en gros œuvre et nouerez des contacts précieux avec des professionnels expérimentés.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur BTP, Génie Civil ou en BTS/DUT Génie Civil (Bac+2 à Bac+5)\r\n- Goût prononcé pour le terrain et le contact avec les équipes\r\n- Sens de l\'organisation et capacité à gérer plusieurs tâches simultanément\r\n- Permis B apprécié', 'Lyon', '5 mois', 550.00, '2026-04-01', '2026-02-18 10:00:00'),
(15, 7, 'Stage – Ingénieur(e) Méthodes & Planification Chantier', 'GTM Construction, filiale de Vinci Construction, est reconnue pour son expertise dans la réalisation de projets complexes en milieu urbain dense. Notre département Méthodes & Innovation joue un rôle clé dans la préparation des chantiers, en définissant les modes opératoires, les installations de chantier et les plannings d\'exécution détaillés qui conditionnent la réussite de nos projets.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recrutons un(e) stagiaire Ingénieur(e) Méthodes & Planification pour rejoindre notre équipe parisienne. Vous interviendrez sur plusieurs projets en phase d\'étude et de démarrage, en apportant votre support méthodologique aux équipes travaux.\r\n\r\nVOS MISSIONS\r\n\r\n- Élaborer et mettre à jour les plannings généraux et détaillés d\'exécution (niveaux 2 et 3) avec MS Project et Primavera P6\r\n- Réaliser les études de méthodes : définition du phasage des travaux, conception des installations de chantier, choix des engins et équipements\r\n- Calculer les ratios de main-d\'œuvre et optimiser l\'organisation des équipes\r\n- Participer à l\'élaboration des Plans d\'Installation de Chantier (PIC) en DAO\r\n- Contribuer à la rédaction des mémoires techniques pour les réponses aux appels d\'offres\r\n- Analyser les écarts planning et proposer des solutions de rattrapage\r\n- Participer aux réunions de coordination avec les équipes travaux et les clients\r\n\r\nOUTILS UTILISÉS\r\n\r\nPlanification : MS Project, Primavera P6\r\nDAO : AutoCAD, SketchUp (visualisation 3D des installations)\r\nBIM 4D : Synchro (simulation du phasage)\r\nBureautique : Suite Office avancée\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expertise en planification et méthodes de chantier qui constitue un avantage compétitif majeur dans le secteur du BTP. Vous apprendrez à anticiper les problèmes avant qu\'ils ne surviennent sur le terrain et développerez une vision stratégique de la conduite de travaux.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur Génie Civil / BTP ou Master TP (Bac+4/5)\r\n- Maîtrise de MS Project ou Primavera souhaitée\r\n- Esprit analytique, rigueur et sens de l\'anticipation\r\n- Aisance avec les logiciels de DAO (AutoCAD apprécié)', 'Paris', '6 mois', 577.50, '2026-04-15', '2026-03-05 10:00:00'),
(16, 8, 'Stage – Développeur(euse) Intelligence Artificielle & NLP', 'IBM, fondée en 1911, est l\'une des entreprises technologiques les plus influentes au monde. En France, IBM emploie plus de 5 000 collaborateurs et s\'est imposé comme un leader du cloud hybride, de l\'intelligence artificielle et de la cybersécurité avec des solutions comme IBM Cloud, Watson et IBM Security. Notre centre de R&D parisien travaille sur des projets d\'IA de pointe pour des clients de rang mondial.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez l\'équipe IBM Client Engineering France et participez au développement de solutions d\'intelligence artificielle basées sur les technologies IBM Watson et les derniers modèles de langage (LLM). Vous travaillerez sur des projets concrets pour des clients des secteurs bancaire, industriel et public.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer et entraîner des modèles de traitement du langage naturel (NLP) : classification de textes, extraction d\'entités, analyse de sentiments, chatbots\r\n- Intégrer des modèles de langage (GPT-4, Llama, IBM Granite) dans des applications métier via API\r\n- Construire des pipelines de données pour la préparation et l\'augmentation des jeux d\'entraînement\r\n- Évaluer les performances des modèles (F1-score, BLEU, ROUGE) et proposer des optimisations\r\n- Déployer des modèles en production via IBM Watson Studio et watsonx.ai\r\n- Rédiger de la documentation technique et des guides d\'utilisation\r\n- Présenter les résultats et démos aux équipes clients\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : Python (Transformers, LangChain, spaCy, NLTK)\r\nPlateformes IA : IBM watsonx.ai, IBM Watson NLP, OpenAI API\r\nMLOps : MLflow, Docker, Kubernetes\r\nCloud : IBM Cloud, AWS\r\nOutils : Jupyter Notebook, Git, VS Code\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous travaillerez sur les technologies d\'IA les plus avancées du marché dans un contexte professionnel exigeant. Vous apprendrez à concevoir des solutions IA de bout en bout, de la compréhension du besoin métier au déploiement en production, et à communiquer vos travaux à des interlocuteurs non-techniques.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master Data Science, IA / NLP ou école d\'ingénieur avec spécialisation Machine Learning (Bac+4/5)\r\n- Maîtrise de Python et des bibliothèques NLP (spaCy, Transformers, NLTK)\r\n- Connaissance des architectures Transformer (BERT, GPT) appréciée\r\n- Curiosité intellectuelle, rigueur et capacité à travailler en autonomie\r\n- Anglais professionnel courant (réunions et documentation en anglais)', 'Paris', '6 mois', 600.00, '2026-04-01', '2026-01-25 10:00:00'),
(17, 8, 'Stage – Ingénieur(e) Cloud Hybride & OpenShift', 'IBM Technology est le bras technologique d\'IBM, spécialisé dans le déploiement de solutions cloud hybride pour les entreprises qui souhaitent combiner cloud public et infrastructure on-premise. Notre centre de Sophia Antipolis, au cœur de la Silicon Valley européenne, regroupe des équipes d\'experts cloud, DevOps et architecture intervenant pour des clients de premier plan dans les secteurs bancaire, assurance et santé.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recherchons un(e) stagiaire Ingénieur(e) Cloud & Infrastructure pour renforcer nos équipes de Sophia Antipolis. Vous interviendrez sur des projets d\'architecture cloud hybride à fort enjeu, combinant IBM Cloud, Red Hat OpenShift et des infrastructures on-premise complexes.\r\n\r\nVOS MISSIONS\r\n\r\n- Participer à la conception et au déploiement d\'architectures cloud hybride (IBM Cloud + datacenter client)\r\n- Administrer et opérer des clusters Red Hat OpenShift (installation, upgrade, gestion des workloads)\r\n- Automatiser le provisionnement des infrastructures via Terraform et la configuration via Ansible\r\n- Mettre en œuvre des solutions de monitoring et d\'alerting (Prometheus, Grafana, IBM Instana)\r\n- Réaliser des tests de charge, de résilience (chaos engineering) et de basculement\r\n- Participer aux workshops d\'architecture avec les clients et les équipes IBM\r\n- Rédiger les documentations d\'architecture et les runbooks opérationnels\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nCloud : IBM Cloud, Red Hat OpenShift, VMware\r\nIaC : Terraform, Ansible, Helm Charts\r\nConteneurs : Docker, Kubernetes, Podman\r\nMonitoring : Prometheus, Grafana, IBM Instana, ELK\r\nCI/CD : Tekton, ArgoCD, GitLab CI\r\nSystèmes : Linux RHEL/Ubuntu, Windows Server\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expertise sur Red Hat OpenShift et les architectures cloud hybride, technologies très recherchées sur le marché. Vous préparerez idéalement les certifications Red Hat (RHCSA) et IBM Cloud Practitioner et bénéficierez d\'un accès aux formations IBM certifiantes.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master systèmes/réseaux/cloud (Bac+4/5)\r\n- Bonnes connaissances Linux (administration de base, scripting Bash)\r\n- Première expérience pratique avec Docker et Kubernetes (projets perso ou académiques)\r\n- Curiosité technique, autonomie et esprit d\'équipe', 'Sophia Antipolis', '6 mois', 600.00, '2026-05-01', '2026-02-28 10:00:00'),
(18, 9, 'Stage – Développeur(euse) Backend Node.js – Orange Innovation', 'Orange Innovation est la direction R&D d\'Orange Group, l\'un des principaux opérateurs de télécommunications mondiaux avec plus de 290 millions de clients dans 26 pays. Nos 9 000 chercheurs et ingénieurs répartis dans 20 pays travaillent sur les technologies de demain : réseaux 6G, intelligence artificielle, sécurité numérique et services cloud. En France, notre centre parisien développe des services numériques innovants pour les clients grand public et entreprises.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nAu sein de l\'équipe produit Orange Business Services, rejoignez une squad agile chargée de développer une plateforme de services cloud destinée aux PME et ETI françaises. Vous travaillerez sur le back-end de cette plateforme en forte croissance, avec des enjeux de scalabilité, de performance et de sécurité.\r\n\r\nVOS MISSIONS\r\n\r\n- Concevoir et développer de nouvelles API REST en Node.js/Express selon les spécifications des Product Owners\r\n- Participer à l\'architecture des nouveaux microservices (communication asynchrone via Kafka, RabbitMQ)\r\n- Implémenter des tests unitaires, d\'intégration et end-to-end (Jest, Supertest, Cypress)\r\n- Optimiser les performances des APIs (caching Redis, optimisation des requêtes SQL)\r\n- Contribuer à la sécurisation des endpoints (authentification JWT, OAuth2, rate limiting)\r\n- Participer activement aux cérémonies Agile de la squad (planning, daily, review, rétro)\r\n- Collaborer avec les développeurs front-end et les équipes DevOps\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nBack-end : Node.js, Express.js, NestJS\r\nBase de données : PostgreSQL, MongoDB, Redis\r\nMessaging : Apache Kafka, RabbitMQ\r\nDevOps : Docker, Kubernetes, GitLab CI/CD\r\nSécurité : JWT, OAuth2, Keycloak\r\nMonitoring : Datadog, ELK Stack\r\nOutils : VS Code, Postman, JIRA, Confluence\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez vos compétences en développement back-end Node.js dans un environnement microservices à grande échelle. Vous apprendrez les patterns d\'architecture logicielle modernes (CQRS, Event Sourcing) et les pratiques de développement d\'un opérateur télécom.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) Bac+4/5 en informatique ou école d\'ingénieur\r\n- Bonne maîtrise de JavaScript/TypeScript et de Node.js\r\n- Connaissance des bases de données SQL (PostgreSQL, MySQL)\r\n- Familiarité avec les concepts REST API et les tests automatisés\r\n- Autonomie, sens du détail et goût pour le clean code', 'Paris', '6 mois', 577.50, '2026-04-01', '2026-02-08 10:00:00'),
(19, 9, 'Stage – Ingénieur(e) Réseaux & Télécoms 5G', 'Orange, premier opérateur télécom en France, est engagé dans le déploiement de la 5G sur l\'ensemble du territoire national. Notre direction Orange Réseaux Nouvelle-Aquitaine pilote le déploiement et l\'optimisation des réseaux mobiles 4G et 5G, de la fibre optique et des solutions de connectivité pour les entreprises et les collectivités de la région.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre de l\'accélération du déploiement du réseau 5G SA (Standalone) en Nouvelle-Aquitaine, Orange recrute un(e) stagiaire Ingénieur(e) Réseaux pour rejoindre son équipe de planification et d\'optimisation réseau à Bordeaux.\r\n\r\nVOS MISSIONS\r\n\r\n- Participer à la planification radio des nouvelles stations 5G (dimensionnement, couverture, capacité)\r\n- Analyser les indicateurs de performance réseau (KPIs) : taux de succès d\'appels, débits, disponibilité\r\n- Identifier les zones de faiblesse réseau et proposer des actions correctives (réorientation d\'antennes, ajout de sites)\r\n- Réaliser des mesures de terrain (drive tests) pour valider les modèles de propagation\r\n- Contribuer aux études de faisabilité pour le déploiement de nouvelles technologies (OpenRAN, C-V2X)\r\n- Rédiger des rapports d\'analyse et de recommandations techniques\r\n- Participer aux réunions de coordination avec les équipes déploiement et les sous-traitants\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nOutils radio : Atoll, Planet (planification radio)\r\nAnalyse KPIs : TEMS Investigation, ACTIX Analyzer\r\nSIG : ArcGIS, QGIS\r\nTechnologies : 4G LTE, 5G NR SA/NSA, NG-RAN, MME/AMF\r\nBureautique : Suite Office, Python pour scripts d\'analyse\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expertise rare sur les réseaux mobiles 5G, un domaine en pleine expansion. Vous comprendrez les enjeux économiques et techniques du déploiement d\'un réseau national et développerez des compétences en analyse de données et en modélisation radio.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master Réseaux & Télécommunications (Bac+4/5)\r\n- Connaissances en radiocommunications mobiles (4G/5G appréciées)\r\n- Goût pour l\'analyse de données et la résolution de problèmes techniques\r\n- Permis B indispensable pour les déplacements terrain', 'Bordeaux', '6 mois', 577.50, '2026-06-01', '2026-03-15 10:00:00'),
(20, 10, 'Stage – Technicien(ne) Électricité Courants Forts', 'SPIE Ouest-Centre est la filiale régionale de SPIE, leader européen indépendant des services multi-techniques dans les domaines de l\'énergie et des communications. Avec plus de 2 500 collaborateurs en Pays de la Loire, Bretagne et Centre-Val de Loire, nous intervenons sur l\'ensemble du cycle de vie des installations électriques : conception, installation, maintenance et exploitation.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du développement de son activité en Loire-Atlantique, SPIE Ouest-Centre recrute un(e) stagiaire Technicien(ne) Électricité Courants Forts pour intervenir sur des chantiers tertiaires et industriels. Vous serez intégré(e) à une équipe de techniciens expérimentés sur des projets de construction neuve et de rénovation.\r\n\r\nVOS MISSIONS\r\n\r\n- Participer à l\'installation, au câblage et à la mise en service de tableaux électriques HTA et BTA\r\n- Réaliser le cheminement de câbles et le raccordement des équipements (disjoncteurs, variateurs, onduleurs)\r\n- Établir et contrôler des schémas électriques unifilaires et multifils avec AutoCAD Electrical\r\n- Réaliser les tests et mesures de réception (vérification d\'isolement, essais fonctionnels)\r\n- Assister les techniciens lors des phases de réception et de mise en service chez le client\r\n- Rédiger les fiches de contrôle et les documents de recette\r\n- Respecter les consignes de sécurité électrique (habilitations B1, B2 en cours d\'acquisition)\r\n\r\nENVIRONNEMENT TECHNIQUE\r\n\r\nOutils DAO : AutoCAD Electrical\r\nAppareils de mesure : multimètre, contrôleur d\'isolement, analyseur de réseau\r\nNormes : NF C 15-100, NFC 13-100, IEC 60364\r\nHabilitations électriques : formation à obtenir en début de stage\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nCe stage vous permettra d\'acquérir vos premières habilitations électriques et de développer des compétences pratiques en installation électrique industrielle et tertiaire. Vous découvrirez les métiers de l\'énergie au sein d\'un leader européen et renforcerez votre employabilité dans un secteur en forte demande.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en BTS Électrotechnique, DUT GEII ou Licence Pro Énergie et Génie Climatique (Bac+2 à Bac+3)\r\n- Bases solides en électrotechnique et en lecture de schémas électriques\r\n- Sérieux, rigueur et respect des consignes de sécurité\r\n- Goût pour le terrain et le travail manuel', 'Nantes', '4 mois', 530.00, '2026-04-06', '2026-02-22 10:00:00'),
(21, 10, 'Stage – Chargé(e) d\'Affaires Génie Climatique CVC', 'SPIE Industrie & Tertiaire, filiale de SPIE France, est spécialisée dans les installations de génie climatique (CVC : Chauffage, Ventilation, Climatisation) pour des clients industriels et tertiaires exigeants. Notre agence lyonnaise, forte de 180 collaborateurs, intervient sur des projets de grande envergure : centres de données, hôpitaux, laboratoires pharmaceutiques et bâtiments tertiaires de nouvelle génération.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recherchons un(e) stagiaire Chargé(e) d\'Affaires CVC pour renforcer notre pôle commercial et technique à Lyon. Vous participerez à la réponse à des appels d\'offres et au suivi de chantiers d\'installations CVC complexes.\r\n\r\nVOS MISSIONS\r\n\r\n- Réaliser le chiffrage et l\'établissement d\'offres techniques et commerciales pour des projets CVC\r\n- Effectuer des bilans thermiques et des calculs de dimensionnement (aéraulique, hydraulique)\r\n- Assurer le suivi technique et financier des chantiers en cours\r\n- Coordonner les interventions des techniciens et sous-traitants sur chantier\r\n- Participer aux réunions de chantier et aux réceptions de travaux\r\n- Gérer les relations clients et fournisseurs au quotidien\r\n- Assurer le reporting hebdomadaire au responsable d\'affaires\r\n\r\nOUTILS UTILISÉS\r\n\r\nLogiciels métier : Pleiades, Ecodial, Climawin (calculs thermiques et aérauliques)\r\nDAO : AutoCAD MEP\r\nGestion : Suite Office, logiciel de gestion d\'affaires interne\r\nNormes : RT 2012, RE 2020, réglementation amiante et fluides frigorigènes\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous découvrirez le métier de chargé d\'affaires dans toute sa dimension technique et commerciale. Vous apprendrez à répondre à des appels d\'offres complexes, à dimensionner des installations CVC et à gérer des chantiers en autonomie croissante.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en BTS Fluides Énergies Environnements (FEE), DUT Génie Thermique ou Licence Pro Génie Climatique (Bac+2 à Bac+3)\r\n- Connaissances de base en thermique du bâtiment et en fluides frigorigènes\r\n- Aisance relationnelle et sens du service client\r\n- Organisé(e) et capable de gérer plusieurs affaires en parallèle', 'Lyon', '5 mois', 550.00, '2026-05-04', '2026-03-20 10:00:00');
INSERT INTO `offres` (`id`, `entreprise_id`, `titre`, `description`, `lieu`, `duree`, `remuneration`, `date_debut`, `created_at`) VALUES
(22, 11, 'Stage – Développeur(euse) Logiciel Embarqué Avionique', 'Thales Avionics, filiale de Thales Group, est un équipementier de premier rang dans le domaine de l\'avionique civile et militaire. Basé à Toulouse, notre centre d\'excellence développe les systèmes de navigation, d\'affichage et de gestion de vol des avions de nouvelle génération pour les plus grands constructeurs mondiaux (Airbus, Boeing, Embraer). Thales Avionics emploie plus de 5 000 ingénieurs sur son site toulousain.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recrutons un(e) stagiaire Développeur(euse) Logiciel Embarqué pour rejoindre nos équipes de développement de logiciels avioniques certifiés. Vous travaillerez dans un environnement rigoureux respectant les normes aéronautiques DO-178C (niveau DAL A/B), au sein d\'une équipe de 8 à 10 ingénieurs.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer des composants logiciels embarqués temps réel en C et Ada pour des systèmes d\'affichage avionique\r\n- Analyser les spécifications fonctionnelles et software issues de l\'outil DOORS\r\n- Rédiger des plans de tests bas niveau (LLTRD) et exécuter les tests de couverture structurelle\r\n- Participer aux revues de conception logicielle (PDR, CDR) et aux revues de code\r\n- Utiliser les outils de couverture de code et d\'analyse statique (LDRA, Polyspace)\r\n- Contribuer à la traçabilité exigences-code-tests dans l\'outil de gestion d\'exigences\r\n- Participer aux activités de vérification et validation selon le processus DO-178C\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : C, Ada 2012\r\nRTOS : RTEMS, VxWorks 653\r\nOutils qualité : LDRA Testbed, Polyspace Bug Finder, Cantata\r\nGestion des exigences : IBM DOORS, PTC Integrity\r\nConfiguration : ClearCase, Git\r\nNormes : DO-178C (DAL B), DO-254, ARP 4754A\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nCe stage vous plongera dans l\'univers exigeant du développement logiciel avionique certifié. Vous maîtriserez les processus DO-178C, les outils de couverture de code et les méthodes de développement formelles. C\'est une expérience rare et très valorisée sur le marché aéronautique et de la défense.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master informatique / systèmes embarqués (Bac+4/5)\r\n- Maîtrise du langage C ; connaissance d\'Ada un plus\r\n- Rigueur absolue, méthode et souci de la qualité\r\n- Intérêt pour l\'aéronautique et les systèmes critiques\r\n- Niveau d\'anglais technique correct', 'Toulouse', '6 mois', 600.00, '2026-04-01', '2026-01-30 10:00:00'),
(23, 11, 'Stage – Ingénieur(e) Cybersécurité – Systèmes de Défense', 'Thales Digital Identity & Security est la Business Unit de Thales dédiée à la cybersécurité et à la protection des systèmes d\'information. Avec 3 000 experts cyber répartis dans le monde, nous sécurisons les communications et les données des gouvernements, armées, opérateurs d\'importance vitale (OIV) et grandes entreprises. Notre centre parisien est un hub d\'excellence en sécurité des systèmes industriels et souverains.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans un contexte de menaces cyber croissantes sur les systèmes de défense et les infrastructures critiques, Thales DIS recrute un(e) stagiaire Ingénieur(e) Cybersécurité pour rejoindre son équipe Évaluation & Conseil à Paris. Vous travaillerez sur des projets classifiés et non classifiés pour des clients ministériels et industriels de la BITD (Base Industrielle et Technologique de Défense).\r\n\r\nVOS MISSIONS\r\n\r\n- Réaliser des analyses de risques de sécurité sur des systèmes d\'information sensibles (méthode EBIOS Risk Manager)\r\n- Participer à des tests d\'intrusion (pentest) sur des applications web, des réseaux et des systèmes industriels (SCADA/ICS)\r\n- Rédiger des politiques de sécurité, des guides de configuration (hardening) et des procédures de sécurité\r\n- Contribuer à la qualification de solutions de sécurité auprès de l\'ANSSI\r\n- Assurer une veille technique approfondie sur les APT (Advanced Persistent Threats) et les techniques MITRE ATT&CK\r\n- Participer à des exercices de simulation d\'incidents cyber (cyber wargames)\r\n- Rédiger des rapports d\'audit et des recommandations techniques à destination de clients exigeants\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nAnalyse de risques : EBIOS RM, ISO 27001/27005\r\nPentest : Metasploit, Burp Suite, Nmap, Mimikatz, BloodHound\r\nSystèmes industriels : Wireshark, Claroty, Nozomi (ICS/SCADA)\r\nThreat Intelligence : MISP, OpenCTI, MITRE ATT&CK Framework\r\nCryptographie : PKI, TLS, chiffrement souverain (RGS)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expertise en cybersécurité de haut niveau dans un contexte souverain, avec une exposition à des menaces réelles et des systèmes critiques. Ce stage ouvre des portes vers les métiers les plus recherchés en cybersécurité : analyste threat intelligence, auditeur de sécurité, consultant SSI.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master ou école d\'ingénieur Cybersécurité / SSI (Bac+4/5)\r\n- Solides connaissances en réseaux, systèmes Linux/Windows et sécurité des SI\r\n- Intérêt pour les problématiques de sécurité nationale et de défense\r\n- Habilitation Secret Défense en cours ou susceptible d\'être accordée\r\n- Discrétion absolue, rigueur et sens des responsabilités', 'Paris', '6 mois', 600.00, '2026-05-04', '2026-02-14 10:00:00'),
(24, 12, 'Stage – Ingénieur(e) Travaux Autoroutes & Ouvrages d\'Art', 'Vinci Autoroutes est le premier groupe concessionnaire d\'autoroutes en France, exploitant plus de 4 400 km de réseau sur les axes les plus fréquentés du pays (A6, A7, A10, A71…). Notre direction des Travaux Île-de-France est en charge de la maintenance préventive et curative du réseau, des chantiers de renforcement et des grands programmes d\'investissement pour améliorer la sécurité et la capacité du réseau.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre d\'un programme pluriannuel de réhabilitation de chaussées et de renforcement d\'ouvrages d\'art sur l\'axe A6/A10 en Île-de-France, Vinci Autoroutes recrute un(e) stagiaire Ingénieur(e) Travaux. Vous serez rattaché(e) à un chef de projet expérimenté et interviendrez sur des chantiers réalisés en milieu contraint (circulation maintenue, nuit, weekend).\r\n\r\nVOS MISSIONS\r\n\r\n- Suivre quotidiennement l\'avancement des travaux de chaussée (retraitement, enrobés, signalisation horizontale) et d\'ouvrages d\'art (inspection, réparation béton, étanchéité)\r\n- Coordonner les équipes Vinci et les sous-traitants spécialisés (entreprises d\'enrobés, entreprises de génie civil)\r\n- Contrôler la qualité des matériaux mis en œuvre (essais Proctor, Marshall, carottages)\r\n- Préparer et suivre les balisages et déviations de circulation lors des interventions nocturnes\r\n- Participer à la rédaction des comptes-rendus de réunion et des rapports d\'avancement mensuels\r\n- Contribuer au suivi budgétaire et à la gestion des marchés de sous-traitance\r\n- Veiller au strict respect des plans de management QHSE du projet\r\n\r\nOUTILS UTILISÉS\r\n\r\nPlanification : MS Project\r\nDAO : AutoCAD\r\nContrôle qualité : logiciel de suivi qualité interne Vinci\r\nNormes : EN 13108 (enrobés bitumineux), STER 11, ICTAAL\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous découvrirez les spécificités des travaux autoroutiers (contraintes de circulation, travaux de nuit, sécurité des chantiers ouverts à la circulation) et développerez une expertise en maintenance et réhabilitation d\'infrastructures routières et d\'ouvrages d\'art.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master Travaux Publics / Génie Civil (Bac+4/5)\r\n- Intérêt pour les travaux de chaussée et les ouvrages d\'art\r\n- Disponibilité pour des astreintes ponctuelles en travaux de nuit (avec compensation)\r\n- Permis B indispensable', 'Paris', '6 mois', 577.50, '2026-04-01', '2026-02-03 10:00:00'),
(25, 12, 'Stage – Chargé(e) de Mission RSE & Développement Durable', 'Vinci Construction est l\'un des leaders mondiaux de la construction avec 70 000 collaborateurs et des activités dans plus de 100 pays. Engagé dans la transition écologique, le groupe a pris des engagements ambitieux : neutralité carbone en 2030 pour ses opérations directes, réduction de 30% de l\'empreinte carbone de ses projets d\'ici 2030. La direction RSE France pilote cette transformation en lien avec toutes les entités du groupe.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nLa direction RSE de Vinci Construction France recherche un(e) stagiaire Chargé(e) de Mission Développement Durable pour renforcer ses équipes dans la mise en œuvre de la stratégie environnementale du groupe. Vous travaillerez au sein d\'une équipe de 6 personnes, interlocutrice de tous les directeurs de projet France.\r\n\r\nVOS MISSIONS\r\n\r\n- Collecter, consolider et analyser les données d\'empreinte carbone des chantiers (scope 1, 2 et 3) selon la méthodologie Bilan Carbone® et EN 15978\r\n- Contribuer à la rédaction du rapport de performance ESG annuel de Vinci Construction France\r\n- Déployer et animer les formations de sensibilisation au développement durable auprès des équipes chantiers\r\n- Suivre les certifications environnementales des projets (HQE, BREEAM, LEED) et accompagner les équipes dans les démarches\r\n- Réaliser une veille réglementaire et normative (taxonomie européenne, CSRD, RE 2020)\r\n- Participer à l\'élaboration de fiches pratiques sur les matériaux bas carbone et les techniques constructives décarbonées\r\n- Contribuer aux réponses aux questionnaires clients, investisseurs et agences de notation ESG\r\n\r\nOUTILS UTILISÉS\r\n\r\nBilan carbone : outil interne Vinci, Base Empreinte ADEME\r\nReporting ESG : GRI Standards, SASB, TCFD\r\nCertifications : référentiels HQE, BREEAM, LEED\r\nBureautique : Suite Office avancée (Excel, PowerPoint)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez une expertise transversale en RSE appliquée à la construction, secteur au cœur des enjeux de décarbonation. Vous apprendrez à mesurer l\'impact environnemental de projets complexes, à communiquer sur les enjeux durables et à accompagner le changement dans une grande organisation.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master RSE, Développement Durable, ou école d\'ingénieur avec spécialisation Environnement / Énergie (Bac+4/5)\r\n- Connaissance des méthodes de bilan carbone et des certifications environnementales\r\n- Capacité d\'analyse, qualités rédactionnelles et pédagogie\r\n- Intérêt sincère pour les enjeux de transition écologique dans le secteur de la construction', 'Paris', '6 mois', 577.50, '2026-05-01', '2026-03-08 10:00:00'),
(26, 13, 'Stage – Consultant(e) Transformation Digitale', 'Accenture est l\'une des plus grandes sociétés de conseil au monde avec 750 000 collaborateurs dans plus de 120 pays. En France, notre practice Technology accompagne les plus grandes entreprises du CAC 40 dans leurs projets de transformation digitale, d\'innovation technologique et d\'optimisation des opérations. Nos équipes parisiennes interviennent dans des secteurs variés : banque, assurance, industrie, retail et secteur public.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez Accenture Technology et participez à des projets de transformation digitale à fort impact. Vous serez intégré(e) à une équipe pluridisciplinaire de consultants seniors, d\'architectes et de développeurs, et interviendrez sur toutes les phases d\'un projet de conseil.\r\n\r\nVOS MISSIONS\r\n\r\n- Analyser les processus métier des clients et identifier les opportunités de digitalisation et d\'automatisation (RPA, IA, cloud)\r\n- Contribuer à la conception de solutions digitales : définition des use cases, maquettage fonctionnel, architecture cible\r\n- Rédiger des livrables de consulting de haute qualité : études d\'opportunités, cahiers des charges fonctionnels, roadmaps de transformation\r\n- Animer des ateliers de co-construction et de recueil de besoins avec les équipes clients (Product Design Thinking)\r\n- Réaliser des benchmarks technologiques et sectoriels pour alimenter les recommandations stratégiques\r\n- Contribuer à la préparation de présentations exécutives pour les COMEX clients\r\n- Participer à la réponse à des appels d\'offres et à la construction des propositions commerciales\r\n\r\nENVIRONNEMENT & MÉTHODES\r\n\r\nMéthodes : Design Thinking, Agile/SAFe, Lean Management\r\nOutils de modélisation : Figma, Lucidchart, Miro, PowerPoint avancé\r\nOutils projet : JIRA, Confluence, Microsoft Teams\r\nTechnologies suivies : cloud (AWS/Azure), IA générative, automatisation RPA (UiPath, Power Automate)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez une vision stratégique et opérationnelle de la transformation digitale des grandes entreprises. Vous apprendrez à structurer une pensée analytique, à communiquer des recommandations complexes de façon claire et à travailler dans des environnements clients exigeants. Ce stage est un tremplin idéal vers les métiers du conseil en stratégie digitale.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école de commerce, école d\'ingénieur ou Master (Bac+4/5)\r\n- Esprit analytique, curiosité intellectuelle et sens de la synthèse\r\n- Excellentes qualités rédactionnelles et de présentation (PowerPoint)\r\n- Aisance relationnelle et capacité à travailler en équipe multiculturelle\r\n- Anglais courant indispensable (réunions, livrables en anglais fréquents)', 'Paris', '6 mois', 600.00, '2026-04-01', '2026-02-16 10:00:00'),
(27, 13, 'Stage – Développeur(euse) Full Stack Angular / Spring Boot', 'Accenture Technology réunit en France plus de 8 000 ingénieurs et consultants IT organisés en squads produit qui livrent des solutions logicielles à l\'état de l\'art pour des clients grands comptes. Nos équipes pratiquent un engineering de haute qualité : revues de code systématiques, CI/CD, tests automatisés, architecture microservices et pratiques DevSecOps.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez une squad produit d\'Accenture Technology à Paris La Défense et participez au développement d\'une plateforme digitale utilisée par des milliers d\'utilisateurs. Vous évoluerez dans un environnement Agile SAFe avec des pratiques engineering avancées.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer de nouvelles fonctionnalités front-end en Angular 17 (composants, services, routing, RxJS)\r\n- Concevoir et implémenter des endpoints REST et GraphQL côté back-end en Java/Spring Boot\r\n- Rédiger des tests unitaires (JUnit, Jasmine/Karma) et des tests d\'intégration (Postman, RestAssured)\r\n- Participer aux cérémonies Agile SAFe : PI Planning, sprint planning, daily, review et rétrospective\r\n- Contribuer aux revues de code et respecter les standards de qualité de l\'équipe (SonarQube)\r\n- Travailler sur la réduction de la dette technique et l\'amélioration des performances\r\n- Collaborer avec les UX designers pour intégrer les maquettes Figma en respectant le Design System\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nFront-end : Angular 17, TypeScript, RxJS, NgRx, SCSS\r\nBack-end : Java 21, Spring Boot 3, Spring Security, Hibernate\r\nAPI : REST, GraphQL\r\nBase de données : PostgreSQL, Redis\r\nDevOps : Docker, Kubernetes, Azure DevOps, SonarQube\r\nOutils : IntelliJ IDEA, VS Code, Figma, JIRA, Confluence\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez vos compétences full stack dans un environnement de production à grande échelle, avec des pratiques engineering de référence (clean architecture, DDD, TDD). Vous apprendrez à livrer du code de qualité production dans des délais contraints et à collaborer efficacement dans une grande équipe Agile.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) Bac+4/5 en informatique ou école d\'ingénieur\r\n- Maîtrise de Java et d\'un framework front-end (Angular, React ou Vue.js)\r\n- Connaissance des bases de données relationnelles (SQL)\r\n- Rigueur, sens du clean code et goût pour le travail en équipe\r\n- Anglais technique lu/écrit (documentation et code commentés en anglais)', 'Paris', '6 mois', 600.00, '2026-05-04', '2026-03-12 10:00:00'),
(28, 14, 'Stage – Administrateur(rice) Systèmes Linux & Cloud', 'Atos est un leader international de la transformation digitale avec 110 000 collaborateurs dans 71 pays. Notre division Atos Technical & Shared Services opère en France l\'un des plus grands centres de services informatiques d\'Europe, assurant l\'exploitation 24h/24 et 7j/7 de milliers de serveurs pour des clients grands comptes issus des secteurs public, bancaire, industriel et de la santé.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nRejoignez notre centre de services de Nantes et participez à l\'exploitation et à l\'évolution des infrastructures systèmes de nos clients. Vous serez intégré(e) à une équipe de 12 administrateurs systèmes et participerez à toutes les activités opérationnelles du centre.\r\n\r\nVOS MISSIONS\r\n\r\n- Administrer au quotidien des parcs de serveurs Linux (Red Hat Enterprise Linux, Ubuntu Server) et Windows Server\r\n- Déployer et configurer des applications via des scripts Ansible et des manifests Kubernetes\r\n- Surveiller les infrastructures avec les outils de monitoring (Zabbix, Prometheus, Grafana) et traiter les alertes\r\n- Participer à la résolution des incidents de niveau 2 et 3 (diagnostic système, réseau, base de données)\r\n- Automatiser des tâches d\'exploitation récurrentes via des scripts Bash et Python\r\n- Contribuer aux migrations de workloads vers le cloud (Azure, AWS) dans le cadre des projets de modernisation clients\r\n- Rédiger et maintenir la documentation technique (runbooks, procédures d\'exploitation, architectures)\r\n- Participer aux astreintes ponctuelles lors de maintenances planifiées\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nSystèmes : RHEL 8/9, Ubuntu 22.04, Windows Server 2019/2022\r\nConteneurs : Docker, Kubernetes (AKS, EKS), Helm\r\nIaC & Automatisation : Ansible, Terraform, Bash, Python\r\nCloud : Azure (VM, AKS, Azure Monitor), AWS (EC2, RDS)\r\nMonitoring : Zabbix, Prometheus, Grafana, ELK Stack\r\nITSM : ServiceNow (gestion des incidents et des changements)\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expérience opérationnelle solide en administration systèmes Linux et cloud dans un centre de services professionnel. Vous développerez des compétences en automatisation, en troubleshooting avancé et en gestion des incidents, des compétences très recherchées sur le marché IT.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en BTS SIO (option SISR), DUT informatique, ou Bac+3/5 systèmes et réseaux\r\n- Solides connaissances Linux (administration, scripting Bash)\r\n- Notions de virtualisation (VMware, Hyper-V) et de conteneurisation (Docker)\r\n- Rigueur, sens du service et capacité à travailler en équipe sous contrainte de SLA\r\n- Astreintes ponctuelles en soirée/weekend lors de maintenances planifiées', 'Nantes', '6 mois', 550.00, '2026-04-14', '2026-02-24 10:00:00'),
(29, 14, 'Stage – Ingénieur(e) Big Data & Analytics', 'Atos Big Data & Cybersecurity est la division d\'Atos spécialisée dans le traitement de grandes volumétries de données et la valorisation analytique pour des clients publics et privés. Nos équipes parisiennes travaillent sur des projets de data engineering et de business intelligence pour des clients du secteur de la santé, de l\'administration publique et de la finance, avec des enjeux forts en termes de gouvernance et de souveraineté des données.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du développement de sa practice Data Engineering, Atos recrute un(e) stagiaire Ingénieur(e) Big Data & Analytics pour rejoindre une équipe projet travaillant sur une plateforme de données de santé à l\'échelle nationale. Vous participerez à la conception et au développement de pipelines de données critiques.\r\n\r\nVOS MISSIONS\r\n\r\n- Concevoir et développer des pipelines de données batch et streaming en Apache Spark et Apache Kafka\r\n- Modéliser les schémas de données (modèles en étoile, en flocon) pour les entrepôts de données (Azure Synapse, Snowflake)\r\n- Optimiser les performances des requêtes SQL et des jobs Spark (partitionnement, caching, broadcast join)\r\n- Développer et maintenir des dashboards analytiques avec Power BI et Tableau\r\n- Mettre en place des contrôles qualité des données (data quality checks, data lineage)\r\n- Automatiser les workflows de traitement de données avec Apache Airflow\r\n- Documenter les architectures data et rédiger les dictionnaires de données\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nTraitement de données : Apache Spark 3.x, Apache Kafka, Apache Airflow\r\nLangages : Python (PySpark, Pandas), SQL avancé, Scala (notions)\r\nEntrepôts de données : Azure Synapse Analytics, Snowflake, Delta Lake\r\nVisualisation : Power BI, Tableau, Apache Superset\r\nCloud : Azure Data Factory, Azure Data Lake Storage Gen2\r\nOutils : Git, Docker, Databricks, Jupyter\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez une expertise complète en data engineering sur des données à grande échelle dans un contexte professionnel exigeant. Vous apprendrez à concevoir des architectures data robustes, à optimiser des pipelines de traitement et à valoriser les données via des visualisations impactantes.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en Master Data Engineering, Big Data ou école d\'ingénieur informatique (Bac+4/5)\r\n- Maîtrise de Python et de SQL avancé\r\n- Connaissance d\'Apache Spark et/ou d\'un outil de visualisation (Power BI, Tableau) souhaitée\r\n- Rigueur, sens analytique et goût pour les données volumineuses\r\n- Sensibilité aux enjeux de protection des données personnelles (RGPD)', 'Paris', '6 mois', 577.50, '2026-05-01', '2026-03-03 10:00:00'),
(30, 15, 'Stage – Ingénieur(e) Efficacité Énergétique Bâtiment', 'Schneider Electric est le spécialiste mondial de la gestion de l\'énergie et de l\'automatisation, présent dans plus de 100 pays avec 150 000 collaborateurs. Notre offre EcoStruxure, plateforme IoT et cloud ouverte, permet à nos clients industriels, tertiaires et résidentiels d\'optimiser leur consommation d\'énergie, de réduire leur empreinte carbone et d\'améliorer la résilience de leurs installations. Notre centre de R&D et d\'ingénierie de Grenoble est au cœur du développement de ces solutions innovantes.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du déploiement de sa plateforme EcoStruxure Building, Schneider Electric recrute un(e) stagiaire Ingénieur(e) Efficacité Énergétique pour rejoindre son équipe de conseil énergétique à Grenoble. Vous travaillerez directement avec des clients industriels et tertiaires pour les aider à atteindre leurs objectifs de réduction de consommation énergétique.\r\n\r\nVOS MISSIONS\r\n\r\n- Réaliser des audits énergétiques de sites industriels et tertiaires (usines, data centers, hôpitaux, immeubles de bureaux)\r\n- Analyser les consommations énergétiques historiques et identifier les postes de consommation principaux\r\n- Élaborer des plans d\'actions d\'amélioration de l\'efficacité énergétique et calculer les retours sur investissement (ROI)\r\n- Paramétrer et tester les systèmes de gestion technique du bâtiment (GTB/BMS) EcoStruxure Building Operation\r\n- Configurer les tableaux de bord de suivi énergétique en temps réel (Power Monitoring Expert)\r\n- Rédiger des rapports d\'audit et de recommandations techniques à destination des décideurs clients\r\n- Contribuer à la certification ISO 50001 de sites clients (système de management de l\'énergie)\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLogiciels Schneider : EcoStruxure Building Operation, Power Monitoring Expert, EcoStruxure Energy Hub\r\nOutils de calcul : Pleiades Comfie, DesignBuilder (thermique du bâtiment)\r\nNormes : ISO 50001, RE 2020, NF EN 16247 (audit énergétique)\r\nProtocoles : BACnet, Modbus, KNX, SNMP\r\nBureautique : Excel avancé (modélisation financière), PowerPoint\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous acquerrez une expertise complète en conseil en efficacité énergétique et en déploiement de solutions de gestion technique du bâtiment. Ce stage vous permettra de comprendre les enjeux de la transition énergétique dans le monde industriel et tertiaire et de développer des compétences très recherchées dans le contexte de la RE 2020 et des obligations de rénovation énergétique.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master spécialité Énergie, Électrotechnique, Génie Climatique (Bac+4/5)\r\n- Connaissances en thermique du bâtiment et en systèmes électriques\r\n- Goût pour les visites terrain et le contact client\r\n- Rigueur, sens analytique et pédagogie pour restituer des analyses à des non-experts\r\n- Permis B indispensable pour les déplacements sur sites clients', 'Grenoble', '6 mois', 600.00, '2026-04-01', '2026-02-06 10:00:00'),
(31, 15, 'Stage – Développeur(euse) IoT & Firmware Systèmes Connectés', 'Schneider Electric R&D France, basée à Paris et Grenoble, concentre le développement des produits connectés de nouvelle génération. Notre division Digital Energy développe des équipements électriques intelligents communicants (disjoncteurs connectés, compteurs d\'énergie, passerelles IoT) qui collectent des données en temps réel et les transmettent vers nos plateformes cloud pour permettre la supervision et l\'optimisation des installations électriques industrielles.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recrutons un(e) stagiaire Développeur(euse) IoT & Firmware pour rejoindre notre équipe R&D Produits Connectés à Paris. Vous participerez au développement logiciel embarqué d\'une nouvelle gamme de passerelles IoT industrielles communicant via MQTT et 4G/5G avec la plateforme EcoStruxure.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer des firmwares embarqués en C/C++ pour des passerelles IoT sous Linux embarqué (Yocto)\r\n- Implémenter des drivers de communication pour des protocoles industriels (Modbus RTU/TCP, BACnet, IEC 61850)\r\n- Développer le client MQTT pour la communication bidirectionnelle avec la plateforme cloud AWS IoT Core\r\n- Rédiger et exécuter des plans de tests fonctionnels et de robustesse (stress test, tests d\'interopérabilité)\r\n- Contribuer aux activités de cybersécurité produit (hardening firmware, chiffrement TLS, secure boot)\r\n- Participer aux revues de conception et de code avec l\'équipe système\r\n- Documenter les protocoles d\'interface et les APIs du firmware\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : C, C++17, Python (scripts de test)\r\nRTOS / OS : Linux embarqué (Yocto Project), FreeRTOS\r\nProtocoles IoT : MQTT, AMQP, HTTP/REST\r\nProtocoles industriels : Modbus RTU/TCP, BACnet, DLMS/COSEM\r\nCloud : AWS IoT Core, AWS Greengrass\r\nOutils : GCC ARM, Buildroot, Git, JIRA, Confluence\r\nMatériel : STM32, NXP i.MX, modules 4G/5G Sierra Wireless\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez une double expertise en développement firmware embarqué et en IoT industriel, à l\'intersection du monde physique et du cloud. Vous apprendrez à concevoir des systèmes communicants sécurisés et fiables, et travaillerez sur des produits qui seront déployés dans des milliers de sites industriels dans le monde entier.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master systèmes embarqués, électronique, informatique industrielle (Bac+4/5)\r\n- Maîtrise du C/C++ embarqué et bonne connaissance de Linux\r\n- Expérience avec des microcontrôleurs (STM32, ESP32 ou similaire) sur projets académiques ou personnels appréciée\r\n- Passion pour l\'électronique et les objets connectés\r\n- Anglais technique courant (documentation et revues de code en anglais)', 'Paris', '6 mois', 600.00, '2026-06-01', '2026-03-18 10:00:00'),
(32, 16, 'Stage – Ingénieur(e) Systèmes de Cabine Avion – A320 Family', 'Airbus Commercial Aircraft est le premier constructeur mondial d\'avions civils, ayant livré plus de 10 000 appareils à des compagnies aériennes dans le monde entier. À Toulouse, notre Division Cabin & Cargo est responsable de la définition, de l\'intégration et de la certification de tous les systèmes de cabine des familles A320, A330 et A350 : sièges, compartiments bagages, systèmes de divertissement en vol (IFE), éclairage, systèmes d\'oxygène et d\'évacuation d\'urgence.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nDans le cadre du développement de la nouvelle version de la cabine A320neo Cabin Upgrade, Airbus recrute un(e) stagiaire Ingénieur(e) Systèmes de Cabine pour rejoindre l\'équipe Cabin Interior Systems à Toulouse. Vous travaillerez sur la définition et la validation des systèmes d\'éclairage LED et de gestion de la cabine.\r\n\r\nVOS MISSIONS\r\n\r\n- Participer à la définition et au suivi des exigences systèmes de cabine (gestion dans IBM DOORS NG)\r\n- Rédiger et mettre à jour les spécifications fonctionnelles et les Interface Control Documents (ICD)\r\n- Préparer et suivre les essais d\'intégration en atelier cabine (test bench et maquette d\'avion)\r\n- Analyser les non-conformités issues des essais et rédiger les fiches de déviation\r\n- Coordonner les activités avec les équipementiers (Safran Cabin, Collins Aerospace, Panasonic Avionics)\r\n- Préparer les dossiers de certification FAA/EASA pour les modifications de cabine (CS-25, FAR 25)\r\n- Participer aux revues de conception (PDR, CDR, TRR) avec les équipes pluridisciplinaires\r\n\r\nENVIRONNEMENT TECHNIQUE & OUTILS\r\n\r\nGestion des exigences : IBM DOORS NG, Capella (MBSE)\r\nGestion documentaire : Airbus CMS (Documentum)\r\nDAO / 3D : CATIA V5 (consultation), 3DEXPERIENCE (notions)\r\nGestion projet : Planisware, JIRA\r\nNormes : CS-25, DO-160G (environnement électromagnétique), ARP 4754A\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous découvrirez le métier d\'ingénieur systèmes dans le secteur aéronautique civil, avec ses exigences rigoureuses en termes de sécurité, de fiabilité et de certification réglementaire. Vous apprendrez à travailler dans un environnement multiculturel et multisite, avec des équipes et des fournisseurs basés dans le monde entier.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur aéronautique, mécatronique, systèmes embarqués ou électronique (Bac+4/5)\r\n- Connaissance des processus de développement systèmes (cycle en V, MBSE appréciée)\r\n- Anglais courant indispensable (langue de travail quotidienne chez Airbus)\r\n- Rigueur, organisation et capacité à gérer plusieurs sujets en parallèle\r\n- Sensibilité aux enjeux de sécurité aéronautique', 'Toulouse', '6 mois', 600.00, '2026-04-01', '2026-01-28 10:00:00'),
(33, 16, 'Stage – Développeur(euse) Outils de Simulation & Traitement de Données de Vol', 'Airbus Defence & Space est la division d\'Airbus dédiée aux satellites, aux lanceurs spatiaux, aux avions militaires et aux systèmes de défense. Notre centre de Toulouse-Blagnac développe les logiciels de simulation de vol, de traitement des données des essais en vol et d\'analyse des performances aérodynamiques pour les programmes A400M, Eurofighter et Eurodrone. L\'équipe Flight Physics Tools regroupe 30 ingénieurs spécialisés en simulation numérique et traitement de données.\r\n\r\nDESCRIPTION DU POSTE\r\n\r\nNous recrutons un(e) stagiaire Développeur(euse) Outils de Simulation pour renforcer notre équipe Flight Physics Tools. Vous contribuerez au développement et à la maintenance des outils logiciels utilisés quotidiennement par les ingénieurs pour analyser les données des vols d\'essai et valider les modèles aérodynamiques.\r\n\r\nVOS MISSIONS\r\n\r\n- Développer de nouveaux modules de simulation de performances de vol en Python et MATLAB/Simulink\r\n- Créer des outils de traitement et de visualisation des données de vol (paramètres moteur, trajectoires, charges structurales)\r\n- Automatiser les chaînes de post-traitement des données issues des campagnes d\'essais en vol\r\n- Contribuer à la validation et au recalage des modèles aérodynamiques par comparaison avec les données d\'essai\r\n- Développer des interfaces graphiques pour les outils d\'analyse (PyQt, tkinter)\r\n- Rédiger la documentation technique et les guides utilisateur des outils développés\r\n- Participer aux réunions techniques avec les ingénieurs Flight Physics utilisateurs des outils\r\n\r\nENVIRONNEMENT TECHNOLOGIQUE\r\n\r\nLangages : Python 3 (NumPy, SciPy, Pandas, Matplotlib, PyQt), MATLAB/Simulink\r\nDonnées de vol : formats HDF5, TDMS, IADS\r\nSimulation : Dymola (Modelica), AMESim (notions)\r\nCalcul scientifique : méthodes numériques, interpolation, intégration d\'équations différentielles\r\nGestion de version : Git, SVN\r\nOutils Airbus : Airbus Data Analysis Tools (ADAT), CASSIS\r\n\r\nCE QUE VOUS ALLEZ APPRENDRE\r\n\r\nVous développerez une expertise à l\'intersection du développement logiciel scientifique et de la mécanique du vol, un domaine très spécialisé et valorisé dans l\'industrie aéronautique et spatiale. Vous apprendrez à écrire du code scientifique robuste, documenté et maintenable et à travailler en proximité avec des ingénieurs de haut niveau.\r\n\r\nPROFIL RECHERCHÉ\r\n\r\n- Étudiant(e) en école d\'ingénieur ou Master spécialité aéronautique, mécanique des fluides, mécanique, ou informatique scientifique (Bac+4/5)\r\n- Maîtrise de Python scientifique (NumPy, SciPy, Matplotlib) et/ou MATLAB\r\n- Intérêt pour la mécanique du vol, l\'aérodynamique ou la dynamique des systèmes\r\n- Rigueur dans le développement logiciel (tests, documentation, versionnement)\r\n- Anglais professionnel courant (langue de travail dans l\'équipe)', 'Toulouse', '6 mois', 600.00, '2026-05-04', '2026-02-22 10:00:00'),
(34, 1, 'Stage – Développeur(euse) Full Stack PHP/Angular – Aix-en-Provence', 'Sopra Steria, acteur majeur de la Tech en Europe avec 50 000 collaborateurs dans près de 30 pays, recrute un(e) stagiaire Développeur(euse) Full Stack pour rejoindre son agence Sud-Est basée à Aix-en-Provence.\r\n\r\nVOS MISSIONS\r\n\r\nAu sein d\'une équipe projet Agile de 6 personnes, vous interviendrez sur la maintenance évolutive et le développement de nouvelles fonctionnalités d\'une application métier pour un client du secteur de l\'énergie :\r\n\r\nDévelopper des composants back-end en PHP/Symfony et des APIs REST\r\n\r\nDévelopper des interfaces front-end en Angular\r\n\r\nRédiger et exécuter les tests unitaires et d\'intégration\r\n\r\nParticiper aux cérémonies Agile Scrum (daily, sprint review, rétrospective)\r\n\r\nContribuer aux revues de code et à la documentation technique\r\nENVIRONNEMENT TECHNOLOGIQUE\r\nPHP 8, Symfony 6, Angular 16, PostgreSQL, Docker, GitLab CI, Jira', 'Aix-en-Provence', '6', 555.00, '2026-04-02', '2026-04-01 19:11:51');

